def transforms(mask):
    out=[]
    a=mask
    for k in range(4):
        b=[row[:] for row in a]
        for flip in (False, True):
            c=[row[::-1] for row in b] if flip else b
            # normalize to min coordinates, tuples
            pts=tuple(sorted((r,c0) for r,row in enumerate(c) for c0,v in enumerate(row) if v))
            if pts not in out: out.append(pts)
        a=[list(row) for row in zip(*a[::-1])]
    return out

def transform0(g):
    R,C=len(g),len(g[0]); marker=max(set(v for row in g for v in row))
    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==marker]
    # zero based normalize
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    pts=[(r-r0,c-c0) for r,c in pts]
    mask=[[0]*(max(c for r,c in pts)+1) for _ in range(max(r for r,c in pts)+1)]
    for r,c in pts: mask[r][c]=1
    out=[row[:] for row in g]
    for shape in transforms(mask):
        h=max(r for r,c in shape)+1; w=max(c for r,c in shape)+1
        for r in range(R-h+1):
            for c in range(C-w+1):
                if all(g[r+dr][c+dc]==0 for dr,dc in shape):
                    for dr,dc in shape: out[r+dr][c+dc]=marker
    return out
